package cn.workbench;
import org.springframework.stereotype.Service;
import java.util.*;import java.time.*;
import static cn.workbench.Records.*;
@Service public class FormCollectionService {
 final Records r;final Policy p;final Writes w;
 public FormCollectionService(Records r,Policy p,Writes w){this.r=r;this.p=p;this.w=w;}
 boolean manager(Policy.Actor a,Map<String,Object> f){return a.delegationId()==null&&(a.globalAdmin()||a.leader()&&Domain.companyAllowed(a.role(),a.company(),TaskService.integer(f,"companyId")));}
 boolean member(Policy.Actor a,Map<String,Object> f){return a.delegationId()==null&&Objects.equals(a.company(),TaskService.integer(f,"companyId"))&&a.dept()!=null&&departments(f).contains(a.dept())&&(a.departmentHead()||a.role().equals("EMPLOYEE"));}
 List<Integer> departments(Map<String,Object> f){return TaskService.numbers(f.get("departmentIds"));}
 Map<String,Object> form(Policy.Actor a,long id){var f=r.get(id);if(!"FORM_COLLECTION".equals(f.get("kind"))||!manager(a,f)&&!member(a,f))throw ApiException.denied();return f;}
 public List<Map<String,Object>> list(Policy.Actor a){return r.list("FORM_COLLECTION",a.company(),null).stream().filter(f->manager(a,f)||member(a,f)).map(f->summary(a,f)).toList();}
 Map<String,Object> summary(Policy.Actor a,Map<String,Object> f){var out=new LinkedHashMap<>(f);var responses=r.children(TaskService.number(f,"id"),"FORM_RESPONSE");out.put("submitted",responses.stream().filter(x->"SUBMITTED".equals(x.get("status"))).count());out.put("departmentCount",departments(f).size());out.put("canManage",manager(a,f));return out;}
 public Map<String,Object> create(Policy.Actor a,Map<String,Object> b){if(a.delegationId()!=null||!a.allows("TASK_CREATE"))throw ApiException.denied();int company=TaskService.integer(b,"companyId");p.taskLeader(a,company);String title=TaskService.text(b,"title",300);var deadline=TaskService.future(b,"deadline");var depts=TaskService.numbers(b.get("departmentIds"));if(depts.isEmpty()||depts.size()>50||new HashSet<>(depts).size()!=depts.size())throw TaskService.invalid("请选择1至50个不重复部门");for(int id:depts){var d=r.get(id);if(!"DEPARTMENT".equals(d.get("kind"))||TaskService.integer(d,"companyId")!=company||!Boolean.TRUE.equals(d.get("enabled")))throw TaskService.invalid("填报部门必须属于所选公司且已启用");}var f=r.create("FORM_COLLECTION",company,null,null,a.uid(),"ACTIVE",map("title",title,"deadline",deadline.toString(),"departmentIds",depts,"creatorId",a.uid(),"columns",CollectionColumns.read(b.get("columns"))));for(int dept:depts)r.create("FORM_RESPONSE",company,dept,TaskService.number(f,"id"),null,"DRAFT",map("rows",List.of()));w.audit(a,"FORM_COLLECTION_CREATE",TaskService.number(f,"id"));return detail(a,TaskService.number(f,"id"));}
 public Map<String,Object> detail(Policy.Actor a,long id){var f=form(a,id);var out=summary(a,f);out.put("columns",CollectionColumns.read(f.get("columns")));var responses=new ArrayList<Map<String,Object>>();for(var response:r.children(id,"FORM_RESPONSE")){boolean own=member(a,f)&&Objects.equals(a.dept(),TaskService.integer(response,"deptId"));if(!manager(a,f)&&!own)continue;var value=new LinkedHashMap<>(response);value.put("departmentName",r.get(TaskService.number(response,"deptId")).get("name"));boolean submitted="SUBMITTED".equals(response.get("status"));if(!own&&!submitted)value.remove("rows");value.put("canEdit",own&&!submitted&&"ACTIVE".equals(f.get("status"))&&Records.instant(f.get("deadline")).isAfter(Instant.now())&&a.allows("TASK_UPDATE"));responses.add(value);}out.put("responses",responses);return out;}
 @SuppressWarnings("unchecked") public Map<String,Object> save(Policy.Actor a,long id,boolean submit,Map<String,Object> b){form(a,id);var f=r.lock(id);if(!member(a,f)||!a.allows("TASK_UPDATE"))throw ApiException.denied();if(!"ACTIVE".equals(f.get("status"))||!Records.instant(f.get("deadline")).isAfter(Instant.now()))throw new ApiException(409,"FORM_CLOSED","填报已完成或已截止");var response=lockedResponses(id).stream().filter(x->Objects.equals(a.dept(),TaskService.integer(x,"deptId"))).findFirst().orElseThrow(ApiException::denied);response=r.lock(TaskService.number(response,"id"));if("SUBMITTED".equals(response.get("status")))throw new ApiException(409,"FORM_SUBMITTED","本部门已提交，不能再次修改");TaskService.version(response,b);if(!(b.get("rows") instanceof List<?> input)||input.size()>100)throw TaskService.invalid("每部门最多100行");var columns=CollectionColumns.read(f.get("columns"));var keys=CollectionColumns.ids(columns);var rows=new ArrayList<Map<String,Object>>();int total=0;for(Object raw:input){if(!(raw instanceof Map<?,?> item)||!keys.containsAll(item.keySet()))throw TaskService.invalid("表格字段无效");var row=new LinkedHashMap<String,Object>();boolean nonempty=false;for(String key:keys){Object v=item.getOrDefault(key,null);if(v!=null&&!(v instanceof String))throw TaskService.invalid("填报内容必须为文字");String value=v==null?"":((String)v).strip();if(value.length()>2000)throw TaskService.invalid("单元格最多2000字");total+=value.length();if(total>20000)throw TaskService.invalid("每部门填报合计最多20000字");nonempty|=!value.isEmpty();row.put(key,value);}if(!nonempty)continue;if(submit&&keys.contains("content")&&String.valueOf(row.get("content")).isBlank())throw TaskService.invalid("提交时每行必须填写工作内容");rows.add(row);}if(submit&&rows.isEmpty())throw TaskService.invalid("至少填写一条工作事项");response.put("rows",rows);response.put("updatedBy",a.uid());if(submit){response.put("status","SUBMITTED");response.put("submittedAt",Instant.now().toString());}r.save(response);if(submit&&lockedResponses(id).stream().allMatch(x->"SUBMITTED".equals(x.get("status")))){f.put("status","COMPLETED");r.save(f);}w.audit(a,submit?"FORM_RESPONSE_SUBMIT":"FORM_RESPONSE_DRAFT",id);return detail(a,id);}
 // Locking reads also see committed department submissions under MySQL REPEATABLE READ.
 List<Map<String,Object>> lockedResponses(long id){return r.db.lockChildren(id,"FORM_RESPONSE").stream().map(row->r.view(row,true)).toList();}
 public List<String> exportHeaders(Policy.Actor a,long id){var f=form(a,id);if(!manager(a,f))throw ApiException.denied();var headers=new ArrayList<>(List.of("部门","序号"));headers.addAll(CollectionColumns.names(CollectionColumns.read(f.get("columns"))));return headers;}
 public List<List<String>> exportRows(Policy.Actor a,long id){var f=form(a,id);if(!manager(a,f))throw ApiException.denied();var keys=CollectionColumns.ids(CollectionColumns.read(f.get("columns")));var rows=new ArrayList<List<String>>();for(var response:r.children(id,"FORM_RESPONSE")){if(!"SUBMITTED".equals(response.get("status")))continue;String dept=String.valueOf(r.get(TaskService.number(response,"deptId")).get("name"));int index=0;for(Object raw:(List<?>)response.get("rows")){var item=(Map<?,?>)raw;var row=new ArrayList<String>();row.add(dept);row.add(String.valueOf(++index));for(String key:keys)row.add(item.get(key)==null?"":String.valueOf(item.get(key)));rows.add(row);}}return rows;}
}
